<script>
  // Build-time facts injected by vite.config.ts
  const gitHash = __GIT_HASH__;
  const dotCode = __DOT_CODE__;

  // Runtime facts measured in the browser
  let protocol = $state("HTTP");
  /** @type {number | null} */
  let ping = $state(null);
  let region = $state("· · ·");

  $effect(() => {
    const nav = /** @type {PerformanceNavigationTiming | undefined} */ (
      performance.getEntriesByType("navigation")[0]
    );
    const proto = nav?.nextHopProtocol ?? "";
    protocol =
      proto === "h3" ? "HTTP/3"
      : proto === "h2" ? "HTTP/2"
      : proto ? "HTTP/1.1"
      : "HTTP";

    (async () => {
      // Same-origin trace works when the site is proxied through Cloudflare
      // and doubles as the ping probe; speed.cloudflare.com is the CORS-safe
      // fallback for local dev / non-proxied environments.
      try {
        const t0 = performance.now();
        const res = await fetch("/cdn-cgi/trace", { cache: "no-store" });
        if (!res.ok) throw new Error("no trace");
        const text = await res.text();
        ping = Math.max(1, Math.round(performance.now() - t0));
        const kv = Object.fromEntries(
          text.trim().split("\n").map((l) => l.split("=")),
        );
        region = `${kv.loc ?? ""} ${kv.colo ?? ""}`.trim().toUpperCase();
      } catch {
        try {
          const t0 = performance.now();
          const res = await fetch("https://speed.cloudflare.com/meta");
          const meta = await res.json();
          ping = Math.max(1, Math.round(performance.now() - t0));
          // colo is an object ({iata, city, ...}) in current responses,
          // but was a plain code string historically.
          const colo =
            typeof meta.colo === "string" ? meta.colo : (meta.colo?.iata ?? "");
          region = `${meta.country ?? ""} ${colo}`.trim().toUpperCase();
        } catch {
          region = "OFFLINE";
        }
      }
    })();
  });
</script>

