<style>
  .iso {
    position: relative;
    width: 100%;
    aspect-ratio: 174 / 152;
    --depth: 42px;
    transform-style: preserve-3d;
    transition: transform 0.5s;
  }

  .iso:hover {
    transform: rotateX(33deg) rotateY(-45deg);
    /*transform: rotateX(33deg) rotateY(45deg) skew(-33deg) rotateZ(-33deg) scaleY(120%)*/
  }

  .layer {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
  }

  .frame {
    transform: translateZ(calc(var(--depth) * 1.5));
  }

  .spec-text {
    transform: translateZ(calc(var(--depth) * 0.5));
  }

  .badges {
    transform: translateZ(calc(var(--depth) * -0.5));
  }

  .dragon {
    transform: translateZ(calc(var(--depth) * -1.5));
  }

  .spec {
    font-family: InterVariable, Inter, -apple-system, sans-serif;
    font-size: 19.5px;
    font-weight: 700;
    letter-spacing: -0.02em;
    fill: #cecdc3;
  }

  .spec.small {
    font-size: 15px;
  }
</style>
